mapper.update:
update t_quality_verification_result
rule_category = #{ruleCategory}, verification_rule_id = #{verificationRuleId}, error_id = #{errorId}, error_column_name_cn = #{errorColumnNameCn}, error_column_name = #{errorColumnName}, error_column_value = #{errorColumnValue}, error_data = #{errorData}, resource_type = #{resourceType}, problem_type = #{problemType}, rule_description = #{ruleDescription}, modification_suggestions = #{modificationSuggestions}, create_time = #{createTime}, update_time = #{updateTime},
where id = #{id}

mapper.select:
SELECT distinct res.id id, site.`NAME` name, site.id siteId, model.table_name_cn as resourceType, tech.column_name columnName, tech.column_name_cn columnNameCn, brule.rule_name ruleName, brule.rule_description ruleDescription, rule.modification_suggestions modificationSuggestions, res.create_time time, rule.meta_mode_id as modelId FROM t_quality_verification_result res LEFT JOIN sg_tccon_tcsite_b site ON CONCAT( site.id ) = res.error_id LEFT JOIN t_quality_verification_rules rule ON rule.id = res.verification_rule_id LEFT JOIN t_quality_basic_rules brule ON brule.id = rule.rule_id LEFT JOIN t_meta_model_tech tech ON tech.id = rule.meta_model_column_id left join t_meta_model model on rule.meta_mode_id = model.id
and rule.id IS NOT NULL
and site.name like concat('%',#{siteName},'%')
and site.ASSETS_OWNERSHIP_COM_ID = #{ownerId}
and brule.id = #{bRuleId}
and res.rule_category = #{type}
and tech.column_name_cn like concat('%',#{columnName},'%')
and rule.meta_mode_id like concat('%',#{modelId},'%')
UNION SELECT distinct res.id id, site.`NAME` name, site.id siteId, model.table_name_cn as resourceType, '' columnName, '' columnNameCn, brule.rule_name ruleName, brule.rule_description ruleDescription, rule.modification_suggestions modificationSuggestions, res.create_time time, rule.meta_mode_id as modelId
FROM t_quality_verification_result res LEFT JOIN sg_tccon_tcsite_b site ON CONCAT( site.id ) = res.error_id LEFT JOIN t_quality_ass_rule_verification rule ON rule.id = res.verification_rule_id LEFT JOIN t_quality_association_rules brule ON brule.id = rule.verification_rule_id left join t_meta_model model on rule.meta_mode_id = model.id
and rule.id IS NOT NULL
and site.name like concat('%',#{siteName},'%')
and site.ASSETS_OWNERSHIP_COM_ID = #{ownerId}
and brule.id = #{bRuleId}
and res.rule_category = #{type}
and res.error_column_name_cn like concat('%',#{columnName},'%')
and rule.meta_mode_id like concat('%',#{modelId},'%')
ORDER BY name, time desc

SELECT t.tms_id code, t.name name FROM sg_org_company_b t where t.name is not null
and t.name like concat('%', #{name}, '%')
ORDER BY t.name LIMIT 0,10;
